INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_ORIGIN', 'CRE.G8.CREATI.ORIGIN_AND_CONSEQUENCES_', 'cre', 8, 'Tell the origin and consequences of sin (Genesis 3)', ARRAY['CRE.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.a', 'CRE.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.b']::text[], 'The child says Adam and Eve ate the fruit God had forbidden after the serpent tempted them (Genesis 3), and that the results were shame, being sent out of the garden, hard work, pain and death, and separation from God. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_TODAY', 'CRE.G8.CREATI.ORIGIN_AND_CONSEQUENCES_', 'cre', 8, 'Analyse the causes of sin today and the moral values and life skills that help overcome temptation (James 1:13-15; 1 John 2:16; 1 Corinthians 10:13; Matthew 26:41)', ARRAY['CRE.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.c', 'CRE.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.d']::text[], 'Names causes of sin today (evil desires within, peer pressure, the media, greed, pride, idleness, drugs; James 1:14; 1 John 2:16), says God does not tempt anyone (James 1:13), that God gives a way out of every temptation (1 Corinthians 10:13), and names values and life skills that help (self-control, assertiveness, decision-making, prayer and watchfulness as in Matthew 26:41, good company). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["a cause of sin today","a value or life skill for a temptation","what a verse teaches about temptation"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.CREATI.GOD_S_PLAN_FOR_REDEMPTIO.REDEMPTION', 'CRE.G8.CREATI.GOD_S_PLAN_FOR_REDEMPTIO', 'cre', 8, 'Say how God showed love after the fall and planned salvation', ARRAY['CRE.G8.CREATI.GOD_S_PLAN_FOR_REDEMPTIO.a', 'CRE.G8.CREATI.GOD_S_PLAN_FOR_REDEMPTIO.b', 'CRE.G8.CREATI.GOD_S_PLAN_FOR_REDEMPTIO.c']::text[], 'The child says God made clothes for Adam and Eve (Genesis 3:21), promised that the woman''s offspring would defeat the serpent (Genesis 3:15), and that Christians believe He sent Jesus to save people (John 3:16). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_FAITH', 'CRE.G8.THE_BI.FAITH_AND_GOD_S_PROMISES', 'cre', 8, 'Tell the call of Abraham and his faith', ARRAY['CRE.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.a', 'CRE.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.b']::text[], 'The child says God called Abram to leave his country and go to a land God would show him (Genesis 12:1-4), and he obeyed, and that he showed faith by trusting God when he was told to offer Isaac and God provided a ram (Genesis 22). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_PROMISES', 'CRE.G8.THE_BI.FAITH_AND_GOD_S_PROMISES', 'cre', 8, 'Name God''s promises to Abraham', ARRAY['CRE.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.d', 'CRE.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.e']::text[], 'The child names the promises of a land, many descendants, a great name, and a blessing for all families of the earth (Genesis 12:1-3), and says Christians trust God to keep His promises. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANT_ABRAHAM', 'CRE.G8.THE_BI.ABRAHAMIC_COVENANT', 'cre', 8, 'Say what the covenant with Abraham was and its sign', ARRAY['CRE.G8.THE_BI.ABRAHAMIC_COVENANT.b', 'CRE.G8.THE_BI.ABRAHAMIC_COVENANT.c', 'CRE.G8.THE_BI.ABRAHAMIC_COVENANT.d']::text[], 'The child says a covenant is a binding agreement, God made a covenant with Abraham (Genesis 15 and 17) promising land and descendants, and circumcision was the sign of that covenant for his descendants (Genesis 17:10-11). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANTS_TODAY', 'CRE.G8.THE_BI.ABRAHAMIC_COVENANT', 'cre', 8, 'Identify covenants in modern life, evaluate the marks of ungodly covenants and discern them by the word of God', ARRAY['CRE.G8.THE_BI.ABRAHAMIC_COVENANT.a', 'CRE.G8.THE_BI.ABRAHAMIC_COVENANT.e', 'CRE.G8.THE_BI.ABRAHAMIC_COVENANT.f']::text[], 'Names covenants in modern life and their importance (marriage, employment contracts, treaties between nations, church membership and baptism vows, loan agreements); gives marks of ungodly covenants (secret oaths, demands that go against God''s law, harm to self or others, worship of other powers, exploitation, fear and control); and says how to discern them by God''s word (2 Corinthians 6:14-17; Exodus 23:32; Matthew 5:37; 1 John 4:1), seeking a trusted adult or pastor. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["a covenant in modern life and its importance","a mark of an ungodly covenant","how God''s word helps discern"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.KINGSHIP_ISRAEL', 'CRE.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU', 'cre', 8, 'Give reasons for and against kingship in Israel', ARRAY['CRE.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.a', 'CRE.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.b']::text[], 'The child says Israel asked for a king because Samuel was old, his sons did not follow his ways and they wanted to be like other nations (1 Samuel 8), and Samuel warned a king would take their sons, daughters and land for himself. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.SAUL_FAILURES', 'CRE.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU', 'cre', 8, 'Name Saul''s failures and their consequences', ARRAY['CRE.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.c', 'CRE.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.d']::text[], 'The child says Saul offered the sacrifice himself instead of waiting for Samuel (1 Samuel 13) and spared the best of the Amalekites'' flocks against God''s command (1 Samuel 15), and so God rejected him as king. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS', 'CRE.G8.THE_LI.HEALING_OF_BLIND_BARTIMA', 'cre', 8, 'Tell the healing of blind Bartimaeus', ARRAY['CRE.G8.THE_LI.HEALING_OF_BLIND_BARTIMA.a', 'CRE.G8.THE_LI.HEALING_OF_BLIND_BARTIMA.b']::text[], 'The child says Bartimaeus was a blind beggar beside the road at Jericho who called out "Son of David, have mercy on me", Jesus called him, asked what he wanted and said his faith had healed him, and he followed Jesus (Mark 10:46-52). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.THE_LI.CALMING_THE_STORM.CALMING_STORM', 'CRE.G8.THE_LI.CALMING_THE_STORM', 'cre', 8, 'Tell the calming of the storm', ARRAY['CRE.G8.THE_LI.CALMING_THE_STORM.a', 'CRE.G8.THE_LI.CALMING_THE_STORM.b']::text[], 'The child says Jesus was asleep in the boat when a storm rose on the lake, the disciples woke Him in fear, He told the wind and waves to be still, and asked why they had so little faith (Mark 4:35-41). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.THE_LI.HEALING_OF_THE_PARALYTIC.PARALYTIC', 'CRE.G8.THE_LI.HEALING_OF_THE_PARALYTIC', 'cre', 8, 'Tell the healing of the paralytic', ARRAY['CRE.G8.THE_LI.HEALING_OF_THE_PARALYTIC.a', 'CRE.G8.THE_LI.HEALING_OF_THE_PARALYTIC.b', 'CRE.G8.THE_LI.HEALING_OF_THE_PARALYTIC.c']::text[], 'The child says four friends lowered a paralysed man through the roof because of the crowd, Jesus first told him his sins were forgiven, the teachers of the law objected, and Jesus then told him to take up his mat and walk (Mark 2:1-12). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.TEACHI.TEACHINGS_ON_PRAYER.PRAYER', 'CRE.G8.TEACHI.TEACHINGS_ON_PRAYER', 'cre', 8, 'Say what Jesus taught about prayer', ARRAY['CRE.G8.TEACHI.TEACHINGS_ON_PRAYER.a', 'CRE.G8.TEACHI.TEACHINGS_ON_PRAYER.b']::text[], 'The child says Jesus taught the Lord''s Prayer (Matthew 6:9-13), to pray with faith (Mark 11:24) and to keep on praying, as in the story of the friend at midnight (Luke 11:5-10). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.TEACHI.THE_LOST_SHEEP.LOST_SHEEP', 'CRE.G8.TEACHI.THE_LOST_SHEEP', 'cre', 8, 'Tell the parable of the lost sheep', ARRAY['CRE.G8.TEACHI.THE_LOST_SHEEP.a']::text[], 'The child says a shepherd with a hundred sheep left the ninety-nine to look for the one that was lost, rejoiced when he found it, and that there is joy in heaven over one sinner who repents (Luke 15:1-7). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT', 'CRE.G8.THE_CH.THE_HOLY_SPIRIT', 'cre', 8, 'Tell Pentecost and name the fruit of the Spirit', ARRAY['CRE.G8.THE_CH.THE_HOLY_SPIRIT.a', 'CRE.G8.THE_CH.THE_HOLY_SPIRIT.b', 'CRE.G8.THE_CH.THE_HOLY_SPIRIT.d']::text[], 'The child says on the day of Pentecost the Holy Spirit came on the disciples with a sound like wind and tongues like fire and they spoke in other languages (Acts 2), and names the fruit of the Spirit: love, joy, peace, patience, kindness, goodness, faithfulness, gentleness and self-control (Galatians 5:22-23). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.THE_CH.ACTS_OF_COMPASSION.COMPASSION', 'CRE.G8.THE_CH.ACTS_OF_COMPASSION', 'cre', 8, 'Tell the acts of compassion in Matthew 25', ARRAY['CRE.G8.THE_CH.ACTS_OF_COMPASSION.a', 'CRE.G8.THE_CH.ACTS_OF_COMPASSION.c', 'CRE.G8.THE_CH.ACTS_OF_COMPASSION.e', 'CRE.G8.THE_CH.ACTS_OF_COMPASSION.b', 'CRE.G8.THE_CH.ACTS_OF_COMPASSION.d']::text[], 'The child says in Matthew 25:31-46 the king welcomes those who fed the hungry, gave drink to the thirsty, welcomed strangers, clothed the naked, and visited the sick and prisoners, saying whatever was done for the least was done for Him. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.CHRIST.FAMILY_RELATIONSHIPS.FAMILY_ROLES', 'CRE.G8.CHRIST.FAMILY_RELATIONSHIPS', 'cre', 8, 'Name family roles, causes of conflict and healthy practices', ARRAY['CRE.G8.CHRIST.FAMILY_RELATIONSHIPS.a', 'CRE.G8.CHRIST.FAMILY_RELATIONSHIPS.b', 'CRE.G8.CHRIST.FAMILY_RELATIONSHIPS.c', 'CRE.G8.CHRIST.FAMILY_RELATIONSHIPS.e', 'CRE.G8.CHRIST.FAMILY_RELATIONSHIPS.d', 'CRE.G8.CHRIST.FAMILY_RELATIONSHIPS.f']::text[], 'The child names roles of parents (providing, guiding, caring) and children (obeying and helping), healthy practices (talking, sharing duties, forgiving) and causes of conflict (selfishness, lack of listening, quarrels over money), and says children honour parents (Ephesians 6:1-3). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.ABUSE_SAFETY', 'CRE.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI', 'cre', 8, 'Know how to stay safe from abuse and where to get help', ARRAY['CRE.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.a', 'CRE.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.d']::text[], 'The child says abuse means someone hurting, frightening or taking advantage of a child, and says a child who is unsafe or unsure tells a trusted adult such as a parent, teacher or counsellor, and does not keep it secret; values such as self-control and respect keep people safe. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.TEEN_PREGNANCY', 'CRE.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI', 'cre', 8, 'Evaluate causes of teenage pregnancy and examine the consequences of irresponsible sexual behaviour', ARRAY['CRE.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.b', 'CRE.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.c']::text[], 'Evaluates causes of teenage pregnancy (peer pressure, idleness, poverty and gifts for sex, lack of guidance, drugs and alcohol, media, abuse by adults) and examines consequences of irresponsible sexual behaviour (pregnancy, infections including HIV, leaving school, health risks, stigma, guilt, broken family trust, poverty), never blaming a victim of abuse, and names where to get help. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["a cause of teenage pregnancy","a consequence of irresponsible sexual behaviour","what helps avoid it"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_SACRED', 'CRE.G8.CHRIST.SACREDNESS_OF_LIFE', 'cre', 8, 'Tell why life is sacred and where to get help', ARRAY['CRE.G8.CHRIST.SACREDNESS_OF_LIFE.a', 'CRE.G8.CHRIST.SACREDNESS_OF_LIFE.b', 'CRE.G8.CHRIST.SACREDNESS_OF_LIFE.c']::text[], 'The child says life is a gift from God, people are made in His image (Genesis 1:27), and "You shall not murder" (Exodus 20:13), and that a person who feels hopeless should tell a trusted adult or counsellor straight away. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_THREATS', 'CRE.G8.CHRIST.SACREDNESS_OF_LIFE', 'cre', 8, 'Evaluate causes of suicide and of abortion among teenage girls, the consequences of violating the right to life, and the values and life skills that uphold it', ARRAY['CRE.G8.CHRIST.SACREDNESS_OF_LIFE.d', 'CRE.G8.CHRIST.SACREDNESS_OF_LIFE.e', 'CRE.G8.CHRIST.SACREDNESS_OF_LIFE.f', 'CRE.G8.CHRIST.SACREDNESS_OF_LIFE.g']::text[], 'Names causes of suicide (hopelessness, depression, abuse, bullying, family conflict, drugs, exam failure, debt) and says such feelings can be helped; names causes of abortion among teenage girls (fear, shame, pressure, poverty, rejection, pregnancy from abuse); analyses consequences of violating the right to life (loss of life, health complications, guilt and trauma, broken families, legal penalties); compiles values and life skills that uphold life (hope, seeking help early, empathy, self-esteem, chastity, communication); and names where to get help (a parent, teacher, counsellor, pastor, Childline Kenya 116). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["a cause the learner can name","a consequence of violating life","a value or life skill that upholds life","where to get help"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.CHRIST.BULLYING.BULLYING', 'CRE.G8.CHRIST.BULLYING', 'cre', 8, 'Name causes and effects of bullying and values that stop it', ARRAY['CRE.G8.CHRIST.BULLYING.a', 'CRE.G8.CHRIST.BULLYING.b', 'CRE.G8.CHRIST.BULLYING.c']::text[], 'The child names causes (wanting power, jealousy, copying others) and effects (fear, low marks, loneliness), and values from the Bible such as kindness (Ephesians 4:32) and treating others as you wish to be treated (Luke 6:31), and says to tell a trusted adult. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.CHRIST.WORK_TALENTS_GIFTS_AND_A.TALENTS_PARABLE', 'CRE.G8.CHRIST.WORK_TALENTS_GIFTS_AND_A', 'cre', 8, 'Tell the parable of the talents', ARRAY['CRE.G8.CHRIST.WORK_TALENTS_GIFTS_AND_A.c', 'CRE.G8.CHRIST.WORK_TALENTS_GIFTS_AND_A.d']::text[], 'The child says the master gave servants five, two and one talents, the first two traded and doubled theirs, the third buried his, and the master praised the faithful servants and rebuked the one who did nothing (Matthew 25:14-30). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G8.CHRIST.LEISURE.LEISURE', 'CRE.G8.CHRIST.LEISURE', 'cre', 8, 'Tell constructive use of leisure from misuse', ARRAY['CRE.G8.CHRIST.LEISURE.a', 'CRE.G8.CHRIST.LEISURE.b', 'CRE.G8.CHRIST.LEISURE.c', 'CRE.G8.CHRIST.LEISURE.d', 'CRE.G8.CHRIST.LEISURE.f']::text[], 'The child says leisure is free time, names misuse (too much idleness, gambling, drugs, too many games) and its effects (poor school work, poor health) and constructive uses (reading, sport, hobbies, helping at home, rest), and says God gave a day of rest (Exodus 20:8-10). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
