INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_ORIGIN.M_CR8_SO_FRUIT', 'CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_ORIGIN', 'Thinks the forbidden thing was some other food, not the fruit of the tree of the knowledge of good and evil.', '{"question":"What had God forbidden Adam and Eve to eat?","wrong_answer":"The fruit of the tree of life","correct_answer":"The fruit of the tree of the knowledge of good and evil"}'::jsonb, 'The learner has not read Genesis 2:17 closely and fills in any food.', 'Offer "The fruit of the tree of life" beside "The fruit of the tree of the knowledge of good and evil" and ask the child to choose.', 'Read Genesis 2:16-17 and 3:6: the fruit of the tree of the knowledge of good and evil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_ORIGIN.M_CR8_SO_TEMPT', 'CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_ORIGIN', 'Thinks God tempted Eve, instead of the serpent.', '{"question":"Who tempted Eve in the garden?","wrong_answer":"God","correct_answer":"The serpent"}'::jsonb, 'God set the rule, so the learner thinks God set the trap.', 'Offer "God" next to the right answer and ask the question again in a new situation.', 'Read Genesis 3:1 and James 1:13: the serpent tempted; God tempts no one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_ORIGIN.M_CR8_SO_RESULT', 'CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_ORIGIN', 'Thinks the fall changed nothing, missing shame, pain, toil, broken relationships and being sent from the garden.', '{"question":"Name a consequence of the fall in Genesis 3.","wrong_answer":"Nothing changed","correct_answer":"They were sent out of the garden; work became toil and childbirth painful"}'::jsonb, 'The learner does not link sin with loss.', 'Offer "Nothing changed" beside "They were sent out of the garden; work became toil and childbirth painful" and ask the child to choose.', 'List consequences in Genesis 3:14-24: shame, fear, pain, toil, broken relationships, death, sent from the garden.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_TODAY.M_CR8_ST_GOD_TEMPTS', 'CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_TODAY', 'Thinks God sends temptations to make people fall.', '{"question":"According to James 1:13, does God tempt anyone to do evil?","wrong_answer":"Yes, God tempts us to see if we fall","correct_answer":"No: each person is tempted by his own evil desire"}'::jsonb, 'The learner mixes testing (trials that strengthen) with tempting to sin.', 'Offer "Yes, God tempts us to see if we fall" beside "No: each person is tempted by his own evil desire" and ask the child to choose.', 'Read James 1:13-14. Tell testing from tempting: God allows trials, but never pushes to sin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_TODAY.M_CR8_ST_DEVIL_ONLY', 'CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_TODAY', 'Blames every sin on the devil, so the person is not responsible.', '{"question":"Juma steals and says \"the devil made me do it\". What does James 1:14 teach?","wrong_answer":"The devil is fully to blame","correct_answer":"Each person is tempted by his own desire and is responsible for his choice"}'::jsonb, 'Blaming the devil avoids shame, as Adam blamed Eve.', 'Offer "The devil is fully to blame" beside "Each person is tempted by his own desire and is responsible for his choice" and ask the child to choose.', 'Link with Genesis 3:12-13 (blaming) and James 1:14 (own desire). Own the choice and repent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_TODAY.M_CR8_ST_NO_WAY_OUT', 'CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_TODAY', 'Thinks some temptations are too strong to resist, so giving in is unavoidable.', '{"question":"What does 1 Corinthians 10:13 promise about temptation?","wrong_answer":"Some temptations cannot be resisted","correct_answer":"God will not let you be tempted beyond what you can bear and will give a way out"}'::jsonb, 'The learner has felt strong pressure and believes it cannot be resisted.', 'Offer "Some temptations cannot be resisted" beside "God will not let you be tempted beyond what you can bear and will give a way out" and ask the child to choose.', 'Read 1 Corinthians 10:13 and plan a "way out" for three common temptations.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_TODAY.M_CR8_ST_TEMPTED_SINNED', 'CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_TODAY', 'Thinks being tempted is already a sin, so there is no point resisting.', '{"question":"Is it a sin to be tempted?","wrong_answer":"Yes, being tempted is already sin","correct_answer":"No: Jesus was tempted and did not sin; sin is giving in"}'::jsonb, 'A wrong thought feels as guilty as a wrong act.', 'Offer "Yes, being tempted is already sin" beside "No: Jesus was tempted and did not sin; sin is giving in" and ask the child to choose.', 'Read Hebrews 4:15: Jesus was tempted in every way, yet without sin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_ORIGIN.M_CR8_SO_SHAME_HIDE', 'CRES.G8.CREATI.ORIGIN_AND_CONSEQUENCES_.SIN_ORIGIN', 'Forgets that Adam and Eve hid from God out of shame and fear, the first sign of a broken relationship.', '{"question":"What did Adam and Eve do when they heard God walking in the garden (Genesis 3:8)?","wrong_answer":"Ran to greet him","correct_answer":"Hid among the trees"}'::jsonb, 'The learner remembers the eating and the punishment, not what came between.', 'Offer "Ran to greet him" beside "Hid among the trees" and ask the child to choose.', 'Read Genesis 3:8-10 and ask why they hid: shame and fear replaced friendship with God.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CREATI.GOD_S_PLAN_FOR_REDEMPTIO.REDEMPTION.M_CR8_RD_CLOTHES', 'CRES.G8.CREATI.GOD_S_PLAN_FOR_REDEMPTIO.REDEMPTION', 'Thinks God abandoned Adam and Eve after the fall, missing that he made clothes for them (Genesis 3:21).', '{"question":"What did God do for Adam and Eve after the fall?","wrong_answer":"Left them without help","correct_answer":"Made clothes for them"}'::jsonb, 'The learner remembers only the punishment.', 'Offer "Left them without help" next to the right answer and ask the question again in a new situation.', 'Read Genesis 3:21: God made garments of skin and clothed them. Love even in judgement.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CREATI.GOD_S_PLAN_FOR_REDEMPTIO.REDEMPTION.M_CR8_RD_JOHN', 'CRES.G8.CREATI.GOD_S_PLAN_FOR_REDEMPTIO.REDEMPTION', 'Thinks John 3:16 says God gave a new law or a new garden, instead of his only Son.', '{"question":"What does John 3:16 say God gave?","wrong_answer":"A new law","correct_answer":"His one and only Son"}'::jsonb, 'The learner remembers "God so loved the world" and guesses the rest.', 'Offer "A new law" beside "His one and only Son" and ask the child to choose.', 'Recite John 3:16 together and underline "his one and only Son".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CREATI.GOD_S_PLAN_FOR_REDEMPTIO.REDEMPTION.M_CR8_RD_WHY', 'CRES.G8.CREATI.GOD_S_PLAN_FOR_REDEMPTIO.REDEMPTION', 'Does not see that redemption restores the broken relationship between people and God.', '{"question":"Why is redemption important after the fall?","wrong_answer":"It only helps people become rich","correct_answer":"It restores people to friendship with God"}'::jsonb, 'The word redemption is new and abstract.', 'Offer "It only helps people become rich" beside "It restores people to friendship with God" and ask the child to choose.', 'Explain redeem as "buy back"; read Galatians 4:4-5 and Romans 5:8.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CREATI.GOD_S_PLAN_FOR_REDEMPTIO.REDEMPTION.M_CR8_RD_EARN', 'CRES.G8.CREATI.GOD_S_PLAN_FOR_REDEMPTIO.REDEMPTION', 'Thinks people earn salvation by good works, missing God''s grace.', '{"question":"According to Ephesians 2:8-9, how are people saved?","wrong_answer":"By doing enough good works","correct_answer":"By grace through faith, as God''s gift"}'::jsonb, 'At school and home, rewards are earned.', 'Offer "By doing enough good works" beside "By grace through faith, as God''s gift" and ask the child to choose.', 'Read Ephesians 2:8-10: saved by grace, created for good works. Works follow, they do not buy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_FAITH.M_CR8_AF_CALL', 'CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_FAITH', 'Thinks God told Abram to stay in his country, missing "Go from your country".', '{"question":"What did God tell Abram to do?","wrong_answer":"Stay in his country","correct_answer":"Leave his country for a land God would show"}'::jsonb, 'The learner thinks God would not ask someone to leave home.', 'Offer "Stay in his country" next to the right answer and ask the question again in a new situation.', 'Read Genesis 12:1: "Go from your country". Mark Ur, Haran and Canaan on a map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_FAITH.M_CR8_AF_ISAAC', 'CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_FAITH', 'Says God provided a lamb in place of Isaac, from Abraham''s words in 22:8, instead of the ram of 22:13.', '{"question":"What animal did Abraham find to offer instead of Isaac (Genesis 22:13)?","wrong_answer":"A lamb","correct_answer":"A ram caught by its horns"}'::jsonb, 'Abraham told Isaac "God himself will provide the lamb" (Genesis 22:8), so the learner expects a lamb.', 'Offer "A lamb" beside "A ram caught by its horns" and ask the child to choose.', 'Read Genesis 22:8 and 22:13: Abraham said a lamb; God provided a ram caught by its horns.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_FAITH.M_CR8_AF_FAITH', 'CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_FAITH', 'Says Abraham doubted and refused.', '{"question":"How did Abraham respond to God''s call?","wrong_answer":"He refused","correct_answer":"He obeyed"}'::jsonb, 'The learner expects anyone to refuse such a hard call.', 'Offer "He refused" next to the right answer and ask the question again in a new situation.', 'Read Genesis 12:4 and Hebrews 11:8: "Abram went"; by faith he obeyed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_PROMISES.M_CR8_AP_LAND', 'CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_PROMISES', 'Thinks God''s promise to Abraham was mainly gold and wealth, missing descendants, land and blessing.', '{"question":"Which was a promise to Abraham?","wrong_answer":"Great wealth in gold only","correct_answer":"Many descendants"}'::jsonb, 'The learner links blessing with money.', 'Offer "Great wealth in gold only" next to the right answer and ask the question again in a new situation.', 'List the promises of Genesis 12:2-3, 15:5, 17:8: great nation, many descendants, land, blessing to all nations.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_PROMISES.M_CR8_AP_BLESS', 'CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_PROMISES', 'Thinks only Abraham''s family would be blessed, missing "all peoples on earth" (Genesis 12:3).', '{"question":"Who would be blessed through Abraham?","wrong_answer":"Only his family","correct_answer":"All families of the earth"}'::jsonb, 'Family blessings are what the learner knows.', 'Offer "Only his family" next to the right answer and ask the question again in a new situation.', 'Read Genesis 12:3: "all peoples on earth will be blessed through you". Link to Galatians 3:8.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_PROMISES.M_CR8_AP_TRUST', 'CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_PROMISES', 'Thinks God''s promises to Abraham mean nothing to Christians today.', '{"question":"Why do Christians value God''s promises?","wrong_answer":"They are useless","correct_answer":"They can trust God to keep them"}'::jsonb, 'Old promises seem to belong to the past.', 'Offer "They are useless" next to the right answer and ask the question again in a new situation.', 'Show that God kept his promises to Abraham; Christians trust the same God (2 Corinthians 1:20).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_FAITH.M_CR8_AF_SARAH_LAUGH', 'CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_FAITH', 'Forgets that Abraham waited many years for Isaac, thinking the son came at once.', '{"question":"How old was Abraham when Isaac was born (Genesis 21:5)?","wrong_answer":"Still young, soon after the call","correct_answer":"A hundred years old, after waiting many years"}'::jsonb, 'Stories are told quickly and the waiting is lost.', 'Offer "Still young, soon after the call" beside "A hundred years old, after waiting many years" and ask the child to choose.', 'Draw a time line: called at 75, Isaac born at 100. Faith means waiting for God''s promise.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_PROMISES.M_CR8_AP_STARS', 'CRES.G8.THE_BI.FAITH_AND_GOD_S_PROMISES.ABRAHAM_PROMISES', 'Forgets the sign of the stars and thinks God showed Abraham a rainbow.', '{"question":"What did God tell Abram to count to show how many descendants he would have (Genesis 15:5)?","wrong_answer":"The colours of a rainbow","correct_answer":"The stars in the sky"}'::jsonb, 'The rainbow is the covenant sign with Noah.', 'Offer "The colours of a rainbow" beside "The stars in the sky" and ask the child to choose.', 'Read Genesis 15:5 at night if possible: count the stars. Rainbow belongs to Noah (Genesis 9).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANT_ABRAHAM.M_CR8_CA_MEANING', 'CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANT_ABRAHAM', 'Thinks a covenant is a gift.', '{"question":"What is a covenant?","wrong_answer":"A free gift","correct_answer":"A binding agreement"}'::jsonb, 'God''s promises are free, so the learner thinks a covenant is only a gift.', 'Offer "A free gift" next to the right answer and ask the question again in a new situation.', 'Explain covenant: a binding agreement with promises and duties. God promised; Abraham was to walk faithfully (Genesis 17:1).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANT_ABRAHAM.M_CR8_CA_SIGN', 'CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANT_ABRAHAM', 'Gives the rainbow (Noah''s covenant) as the sign of the covenant with Abraham instead of circumcision.', '{"question":"What was the sign of God''s covenant with Abraham?","wrong_answer":"A rainbow","correct_answer":"Circumcision"}'::jsonb, 'The rainbow is the best-known covenant sign.', 'Offer "A rainbow" next to the right answer and ask the question again in a new situation.', 'Make two cards: Noah, rainbow (Genesis 9); Abraham, circumcision (Genesis 17:11).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANT_ABRAHAM.M_CR8_CA_NAME', 'CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANT_ABRAHAM', 'Gives Isaac, his son''s name, as Abram''s new name instead of Abraham.', '{"question":"What was Abram renamed?","wrong_answer":"Isaac","correct_answer":"Abraham"}'::jsonb, 'Isaac is the next name in the family.', 'Offer "Isaac" next to the right answer and ask the question again in a new situation.', 'Read Genesis 17:5: Abram becomes Abraham; Sarai becomes Sarah (17:15).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANTS_TODAY.M_CR8_CT_ALL_GOOD', 'CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANTS_TODAY', 'Thinks every agreement is good if both people agree.', '{"question":"A group asks a youth to swear a secret oath to obey its leader in everything. Is it a good covenant because he agrees?","wrong_answer":"Yes, he agreed, so it is good","correct_answer":"No: a secret oath that demands total obedience to a leader against God''s law is ungodly"}'::jsonb, 'The learner thinks consent alone makes an agreement right.', 'Offer "Yes, he agreed, so it is good" beside "No: a secret oath that demands total obedience to a leader against God''s law is ungodly" and ask the child to choose.', 'List marks of an ungodly covenant: secrecy, against God''s law, harm, control, other powers. Test this oath against them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANTS_TODAY.M_CR8_CT_NOT_COVENANT', 'CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANTS_TODAY', 'Thinks covenants are only in the Bible and none exist today.', '{"question":"Which of these is a covenant in modern life?","wrong_answer":"There are none today","correct_answer":"Marriage vows, or a signed work contract"}'::jsonb, 'The word covenant is met only in Bible lessons.', 'Offer "There are none today" beside "Marriage vows, or a signed work contract" and ask the child to choose.', 'Show a marriage certificate and an employment letter: binding promises with duties on both sides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANTS_TODAY.M_CR8_CT_SECRET_SAFE', 'CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANTS_TODAY', 'Thinks a covenant made in secret is safer because no one can interfere.', '{"question":"What is a warning sign of an ungodly covenant?","wrong_answer":"It is open and others know about it","correct_answer":"It must be kept secret, even from parents and the church"}'::jsonb, 'Secrecy sounds like loyalty.', 'Offer "It is open and others know about it" beside "It must be kept secret, even from parents and the church" and ask the child to choose.', 'Read Ephesians 5:11-13: what is done in darkness is exposed by the light. Godly agreements can be known.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANTS_TODAY.M_CR8_CT_DISCERN_FEELING', 'CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANTS_TODAY', 'Thinks a covenant can be judged good by how exciting or profitable it feels.', '{"question":"How should a Christian discern whether an agreement is godly?","wrong_answer":"By how much money or excitement it brings","correct_answer":"By testing it against God''s word and seeking advice from trusted, godly people"}'::jsonb, 'Quick gain is the loudest measure the learner sees.', 'Offer "By how much money or excitement it brings" beside "By testing it against God''s word and seeking advice from trusted, godly people" and ask the child to choose.', 'Read 1 John 4:1 (test the spirits) and Proverbs 15:22 (plans succeed with many advisers).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANT_ABRAHAM.M_CR8_CA_ONE_SIDED', 'CRES.G8.THE_BI.ABRAHAMIC_COVENANT.COVENANT_ABRAHAM', 'Thinks God''s covenant asked nothing of Abraham.', '{"question":"What did God ask of Abraham in the covenant (Genesis 17:1)?","wrong_answer":"Nothing at all","correct_answer":"To walk before God faithfully and be blameless"}'::jsonb, 'The learner hears only the promises.', 'Offer "Nothing at all" beside "To walk before God faithfully and be blameless" and ask the child to choose.', 'Read Genesis 17:1-2 and 17:9-10: God promised, and Abraham was to walk faithfully and keep the sign.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.KINGSHIP_ISRAEL.M_CR8_KI_REASON', 'CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.KINGSHIP_ISRAEL', 'Says Israel asked for a king because Samuel was young, instead of because he was old and his sons were corrupt.', '{"question":"Why did Israel ask for a king?","wrong_answer":"Samuel was young","correct_answer":"Samuel was old and his sons did not follow his ways"}'::jsonb, 'The learner does not recall why Samuel''s leadership was ending.', 'Offer "Samuel was young" next to the right answer and ask the question again in a new situation.', 'Read 1 Samuel 8:1-5: Samuel was old; his sons took bribes; the people wanted a king like the nations.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.KINGSHIP_ISRAEL.M_CR8_KI_WARNING', 'CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.KINGSHIP_ISRAEL', 'Thinks Samuel said a king would give the people gifts, instead of warning that he would take their sons, land and harvest.', '{"question":"What did Samuel warn a king would do?","wrong_answer":"Give them gifts","correct_answer":"Take their sons and land"}'::jsonb, 'The learner expects a prophet to welcome the people''s wish.', 'Offer "Give them gifts" next to the right answer and ask the question again in a new situation.', 'Read 1 Samuel 8:11-18 and list what a king would take: sons, daughters, fields, a tenth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.KINGSHIP_ISRAEL.M_CR8_KI_NATIONS', 'CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.KINGSHIP_ISRAEL', 'Thinks Israel wanted to be unlike other nations, when they asked to be like them.', '{"question":"What did Israel want, according to 1 Samuel 8:20?","wrong_answer":"To be different from all other nations","correct_answer":"To be like other nations, with a king to lead them"}'::jsonb, 'The phrase "like the nations" is read the wrong way round.', 'Offer "To be different from all other nations" beside "To be like other nations, with a king to lead them" and ask the child to choose.', 'Read 1 Samuel 8:5 and 8:20: they wanted to be like other nations, with a king to lead and fight.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.SAUL_FAILURES.M_CR8_SF_SACRIFICE', 'CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.SAUL_FAILURES', 'Thinks Saul waited for Samuel at Gilgal, instead of offering the sacrifice himself.', '{"question":"What did Saul do at Gilgal?","wrong_answer":"Waited for Samuel","correct_answer":"Offered the sacrifice himself"}'::jsonb, 'The learner thinks a king would obey the prophet.', 'Offer "Waited for Samuel" next to the right answer and ask the question again in a new situation.', 'Read 1 Samuel 13:8-13: Saul did not wait and offered the burnt offering himself.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.SAUL_FAILURES.M_CR8_SF_AMALEK', 'CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.SAUL_FAILURES', 'Thinks Saul destroyed all the Amalekite flocks, when he spared the best against God''s command.', '{"question":"What did Saul do with the best Amalekite flocks?","wrong_answer":"Destroyed them","correct_answer":"Spared them"}'::jsonb, 'Sparing the best sounds kind and wise.', 'Offer "Destroyed them" next to the right answer and ask the question again in a new situation.', 'Read 1 Samuel 15:9, 22: "To obey is better than sacrifice". Partial obedience is disobedience.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.SAUL_FAILURES.M_CR8_SF_RESULT', 'CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.SAUL_FAILURES', 'Thinks God made Saul greater after his disobedience, instead of rejecting him as king.', '{"question":"What was the result of Saul''s disobedience?","wrong_answer":"God made him greater","correct_answer":"God rejected him as king"}'::jsonb, 'Kings in stories usually keep their thrones.', 'Offer "God made him greater" next to the right answer and ask the question again in a new situation.', 'Read 1 Samuel 15:23, 26: God rejected Saul as king; David was anointed (1 Samuel 16).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.KINGSHIP_ISRAEL.M_CR8_KI_REJECT_GOD', 'CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.KINGSHIP_ISRAEL', 'Misses that asking for a king was a rejection of God as king.', '{"question":"What did God tell Samuel the people were really rejecting (1 Samuel 8:7)?","wrong_answer":"Samuel","correct_answer":"God as their king"}'::jsonb, 'The learner sees only a quarrel between the people and Samuel.', 'Offer "Samuel" beside "God as their king" and ask the child to choose.', 'Read 1 Samuel 8:7 and discuss why God, not Samuel, was rejected.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.SAUL_FAILURES.M_CR8_SF_OBEY_SACRIFICE', 'CRES.G8.THE_BI.LEADERSHIP_IN_ISRAEL_SAU.SAUL_FAILURES', 'Thinks offering sacrifices pleases God more than obeying him.', '{"question":"What did Samuel tell Saul in 1 Samuel 15:22?","wrong_answer":"Sacrifice is better than obedience","correct_answer":"To obey is better than sacrifice"}'::jsonb, 'Saul''s excuse sounds religious, so the learner accepts it.', 'Offer "Sacrifice is better than obedience" beside "To obey is better than sacrifice" and ask the child to choose.', 'Read 1 Samuel 15:22 and ask: can a gift replace doing what God said?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS.M_CR8_BT_PLACE', 'CRES.G8.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS', 'Places the healing in Jerusalem instead of near Jericho.', '{"question":"Where was Bartimaeus healed?","wrong_answer":"Jerusalem","correct_answer":"Jericho"}'::jsonb, 'Jerusalem is the city most linked with Jesus'' last days.', 'Offer "Jerusalem" next to the right answer and ask the question again in a new situation.', 'Read Mark 10:46: leaving Jericho. Mark it on a map on the road to Jerusalem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS.M_CR8_BT_CRY', 'CRES.G8.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS', 'Gives "Teacher, teach me" as Bartimaeus'' cry instead of "Son of David, have mercy on me".', '{"question":"What did Bartimaeus call out?","wrong_answer":"Teacher, teach me","correct_answer":"Son of David, have mercy on me"}'::jsonb, '"Teacher" is a common title for Jesus.', 'Offer "Teacher, teach me" next to the right answer and ask the question again in a new situation.', 'Read Mark 10:47: "Jesus, Son of David, have mercy on me!" Son of David is a title for the Messiah.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS.M_CR8_BT_RESULT', 'CRES.G8.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS', 'Thinks Bartimaeus went home after being healed, instead of following Jesus.', '{"question":"What did Bartimaeus do after he was healed?","wrong_answer":"Went home alone","correct_answer":"Followed Jesus"}'::jsonb, 'Healed people often go home in the stories.', 'Offer "Went home alone" next to the right answer and ask the question again in a new situation.', 'Read Mark 10:52: he followed Jesus along the road.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS.M_CR8_BT_CLOAK', 'CRES.G8.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS', 'Misses why Bartimaeus threw off his cloak, a beggar''s most valuable thing.', '{"question":"What did Bartimaeus do when Jesus called him (Mark 10:50)?","wrong_answer":"Put on his cloak and walked slowly","correct_answer":"Threw his cloak aside, jumped up and came to Jesus"}'::jsonb, 'The detail seems unimportant to the learner.', 'Offer "Put on his cloak and walked slowly" beside "Threw his cloak aside, jumped up and came to Jesus" and ask the child to choose.', 'Explain a beggar''s cloak was his bed and begging mat; throwing it aside showed eager faith.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_LI.CALMING_THE_STORM.CALMING_STORM.M_CR8_CS_SLEEP', 'CRES.G8.THE_LI.CALMING_THE_STORM.CALMING_STORM', 'Thinks Jesus was steering the boat in the storm, instead of sleeping on a cushion.', '{"question":"What was Jesus doing in the storm?","wrong_answer":"Steering the boat","correct_answer":"Sleeping"}'::jsonb, 'The learner expects Jesus to be in charge of the boat.', 'Offer "Steering the boat" next to the right answer and ask the question again in a new situation.', 'Read Mark 4:38: asleep on a cushion in the stern.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_LI.CALMING_THE_STORM.CALMING_STORM.M_CR8_CS_WORDS', 'CRES.G8.THE_LI.CALMING_THE_STORM.CALMING_STORM', 'Gives a wrong command to the storm instead of "Quiet! Be still!"', '{"question":"What did Jesus say to the wind and the waves?","wrong_answer":"\"Go away from us\"","correct_answer":"\"Quiet! Be still!\""}'::jsonb, 'The learner does not recall the command and picks any words.', 'Offer ""Go away from us"" beside ""Quiet! Be still!"" and ask the child to choose.', 'Read Mark 4:39 aloud: "Quiet! Be still!"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_LI.CALMING_THE_STORM.CALMING_STORM.M_CR8_CS_FAITH', 'CRES.G8.THE_LI.CALMING_THE_STORM.CALMING_STORM', 'Thinks Jesus praised the disciples for their faith, instead of asking why they had so little.', '{"question":"What did Jesus ask the disciples?","wrong_answer":"Why they were so brave","correct_answer":"Why they had so little faith"}'::jsonb, 'The disciples are heroes in the learner''s mind.', 'Offer "Why they were so brave" next to the right answer and ask the question again in a new situation.', 'Read Mark 4:40: "Why are you so afraid? Do you still have no faith?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_LI.CALMING_THE_STORM.CALMING_STORM.M_CR8_CS_FAITH_NO_FEAR', 'CRES.G8.THE_LI.CALMING_THE_STORM.CALMING_STORM', 'Thinks a person with faith will never feel afraid.', '{"question":"Does having faith mean you will never feel afraid?","wrong_answer":"Yes, faith removes all fear","correct_answer":"No: we may feel afraid, but we trust Jesus who is with us"}'::jsonb, 'Jesus'' question makes the learner think all fear is failure.', 'Offer "Yes, faith removes all fear" beside "No: we may feel afraid, but we trust Jesus who is with us" and ask the child to choose.', 'Discuss Psalm 56:3: "When I am afraid, I put my trust in you". Fear is met with trust.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_LI.HEALING_OF_THE_PARALYTIC.PARALYTIC.M_CR8_PL_ROOF', 'CRES.G8.THE_LI.HEALING_OF_THE_PARALYTIC.PARALYTIC', 'Thinks the friends brought the man through the front door, instead of through the roof.', '{"question":"How did the friends bring the man to Jesus?","wrong_answer":"Through the front door","correct_answer":"Through the roof"}'::jsonb, 'Doors are the normal way into a house.', 'Offer "Through the front door" next to the right answer and ask the question again in a new situation.', 'Read Mark 2:4: the crowd blocked the door, so they dug through the roof.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_LI.HEALING_OF_THE_PARALYTIC.PARALYTIC.M_CR8_PL_SINS', 'CRES.G8.THE_LI.HEALING_OF_THE_PARALYTIC.PARALYTIC', 'Thinks Jesus first told the man to take up his mat, instead of first forgiving his sins.', '{"question":"What did Jesus first say to the paralytic?","wrong_answer":"\"Get up, take your mat and go home\"","correct_answer":"\"Son, your sins are forgiven\""}'::jsonb, 'The learner expects a healer to heal the body first.', 'Offer ""Get up, take your mat and go home"" beside ""Son, your sins are forgiven"" and ask the child to choose.', 'Read Mark 2:5 then 2:11: first "Son, your sins are forgiven", then "get up, take your mat".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_LI.HEALING_OF_THE_PARALYTIC.PARALYTIC.M_CR8_PL_OPPOSITION', 'CRES.G8.THE_LI.HEALING_OF_THE_PARALYTIC.PARALYTIC', 'Thinks the disciples objected to Jesus forgiving sins, instead of some teachers of the law.', '{"question":"Who objected to Jesus forgiving sins?","wrong_answer":"The disciples","correct_answer":"The teachers of the law"}'::jsonb, 'The disciples are often slow in the stories, so the learner blames them.', 'Offer "The disciples" next to the right answer and ask the question again in a new situation.', 'Read Mark 2:6-7: some teachers of the law thought he was blaspheming.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_LI.HEALING_OF_THE_PARALYTIC.PARALYTIC.M_CR8_PL_WHY_OPPOSE', 'CRES.G8.THE_LI.HEALING_OF_THE_PARALYTIC.PARALYTIC', 'Does not know why the teachers of the law objected: they said only God can forgive sins.', '{"question":"Why did the teachers of the law object when Jesus forgave the man''s sins (Mark 2:7)?","wrong_answer":"Because the house was too crowded","correct_answer":"Because they said only God can forgive sins, so Jesus was blaspheming"}'::jsonb, 'The learner sees opposition as dislike, not as a claim about God.', 'Offer "Because the house was too crowded" beside "Because they said only God can forgive sins, so Jesus was blaspheming" and ask the child to choose.', 'Read Mark 2:7 and 2:10: Jesus showed he had authority to forgive by healing the man.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.TEACHI.TEACHINGS_ON_PRAYER.PRAYER.M_CR8_PR_LORDS', 'CRES.G8.TEACHI.TEACHINGS_ON_PRAYER.PRAYER', 'Places the Lord''s Prayer in Matthew 1 instead of Matthew 6:9-13.', '{"question":"Where is the Lord''s Prayer in Matthew?","wrong_answer":"Matthew 1","correct_answer":"Matthew 6:9-13"}'::jsonb, 'The learner knows the prayer by heart but not where it is.', 'Offer "Matthew 1" next to the right answer and ask the question again in a new situation.', 'Open Matthew 6:9-13 and Luke 11:2-4 together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.TEACHI.TEACHINGS_ON_PRAYER.PRAYER.M_CR8_PR_FAITH', 'CRES.G8.TEACHI.TEACHINGS_ON_PRAYER.PRAYER', 'Thinks faith is not needed when praying, as long as the words are right.', '{"question":"How should we pray, according to Jesus?","wrong_answer":"Without faith","correct_answer":"With faith"}'::jsonb, 'The learner thinks saying the right words is enough.', 'Offer "Without faith" next to the right answer and ask the question again in a new situation.', 'Read Mark 11:24 and James 1:6: pray believing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.TEACHI.TEACHINGS_ON_PRAYER.PRAYER.M_CR8_PR_PERSIST', 'CRES.G8.TEACHI.TEACHINGS_ON_PRAYER.PRAYER', 'Thinks a Christian should stop praying if God does not answer quickly.', '{"question":"What does the story of the friend at midnight teach?","wrong_answer":"Give up quickly","correct_answer":"Keep on praying"}'::jsonb, 'Unanswered prayer feels like a no.', 'Offer "Give up quickly" next to the right answer and ask the question again in a new situation.', 'Read Luke 18:1: "always pray and not give up", and the parable of the persistent widow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.TEACHI.TEACHINGS_ON_PRAYER.PRAYER.M_CR8_PR_FRIENDS_ONLY', 'CRES.G8.TEACHI.TEACHINGS_ON_PRAYER.PRAYER', 'Thinks Christians should pray only for friends and family, not for enemies or all people.', '{"question":"For whom should Christians pray, according to Matthew 5:44 and 1 Timothy 2:1?","wrong_answer":"Only friends and family","correct_answer":"All people, including enemies and leaders"}'::jsonb, 'Prayer lists at home name family first, and enemies never.', 'Offer "Only friends and family" beside "All people, including enemies and leaders" and ask the child to choose.', 'Read Matthew 5:44 and 1 Timothy 2:1-2 and make a prayer list that includes leaders and someone hard to love.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.TEACHI.THE_LOST_SHEEP.LOST_SHEEP.M_CR8_LS_NUMBER', 'CRES.G8.TEACHI.THE_LOST_SHEEP.LOST_SHEEP', 'Says the shepherd left ten sheep, mixing the parable with the ten coins, instead of ninety-nine.', '{"question":"How many sheep did the shepherd leave?","wrong_answer":"Ten","correct_answer":"Ninety-nine"}'::jsonb, 'The lost coin had ten, and the numbers mix.', 'Offer "Ten" next to the right answer and ask the question again in a new situation.', 'Write the two parables side by side: 100 sheep (99 left), 10 coins (9 left).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.TEACHI.THE_LOST_SHEEP.LOST_SHEEP.M_CR8_LS_ACTION', 'CRES.G8.TEACHI.THE_LOST_SHEEP.LOST_SHEEP', 'Says he ignored the lost sheep.', '{"question":"What did the shepherd do about the lost sheep?","wrong_answer":"Ignored it","correct_answer":"Looked for it"}'::jsonb, 'One out of a hundred seems a small loss.', 'Offer "Ignored it" next to the right answer and ask the question again in a new situation.', 'Read Luke 15:4: he goes after the lost sheep until he finds it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.TEACHI.THE_LOST_SHEEP.LOST_SHEEP.M_CR8_LS_JOY', 'CRES.G8.TEACHI.THE_LOST_SHEEP.LOST_SHEEP', 'Says heaven is sad over a lost sinner.', '{"question":"Who rejoices when one sinner repents?","wrong_answer":"Nobody","correct_answer":"Heaven"}'::jsonb, 'The learner thinks God is mostly angry with sinners.', 'Offer "Nobody" next to the right answer and ask the question again in a new situation.', 'Read Luke 15:7: more rejoicing in heaven over one sinner who repents.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.TEACHI.THE_LOST_SHEEP.LOST_SHEEP.M_CR8_LS_WHO_LOST', 'CRES.G8.TEACHI.THE_LOST_SHEEP.LOST_SHEEP', 'Thinks the lost sheep stands for a lost animal only, not for a person far from God.', '{"question":"Whom does the lost sheep stand for in Jesus'' parable?","wrong_answer":"A real sheep that a farmer lost","correct_answer":"A person who has wandered from God"}'::jsonb, 'The learner stays with the farm picture.', 'Offer "A real sheep that a farmer lost" beside "A person who has wandered from God" and ask the child to choose.', 'Read Luke 15:1-2 and 15:7: Jesus told it about sinners he welcomed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT.M_CR8_HS_DAY', 'CRES.G8.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT', 'Says the Holy Spirit came at Passover instead of Pentecost.', '{"question":"On which day did the Spirit come on the disciples?","wrong_answer":"Passover","correct_answer":"Pentecost"}'::jsonb, 'Passover is the other great festival in the Gospels.', 'Offer "Passover" next to the right answer and ask the question again in a new situation.', 'Read Acts 2:1: the day of Pentecost, fifty days after Passover.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT.M_CR8_HS_SIGN', 'CRES.G8.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT', 'Gives an earthquake as the sign at Pentecost instead of a sound like wind and tongues like fire.', '{"question":"What signs came with the Holy Spirit at Pentecost (Acts 2:2-3)?","wrong_answer":"An earthquake and darkness","correct_answer":"A sound like a violent wind and tongues like fire"}'::jsonb, 'The learner pictures dramatic weather.', 'Offer "An earthquake and darkness" beside "A sound like a violent wind and tongues like fire" and ask the child to choose.', 'Read Acts 2:2-4: a sound like a violent wind, tongues like fire, speaking in other languages.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT.M_CR8_HS_FRUIT', 'CRES.G8.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT', 'Counts anger as a fruit of the Spirit, mixing it with the works of the flesh.', '{"question":"Which is a fruit of the Spirit?","wrong_answer":"Anger","correct_answer":"Love"}'::jsonb, 'Anger can feel justified, so the learner counts it as good.', 'Offer "Anger" next to the right answer and ask the question again in a new situation.', 'Read Galatians 5:19-23: anger is with the works of the flesh; the fruit begins with love.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT.M_CR8_HS_CHURCH_ACTIVITY', 'CRES.G8.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT', 'Thinks church activities are only for adults or only on Sundays, so a youth gains nothing by taking part.', '{"question":"Why is it important for a young person to take part in church activities?","wrong_answer":"It is not important; church is for adults","correct_answer":"It builds faith, responsibility, gifts and friendships with other believers"}'::jsonb, 'The learner sees adults running church and youth sitting.', 'Offer "It is not important; church is for adults" beside "It builds faith, responsibility, gifts and friendships with other believers" and ask the child to choose.', 'List youth activities (choir, ushering, outreach, Sunday school helping) and what each builds. Read Hebrews 10:24-25.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_CH.ACTS_OF_COMPASSION.COMPASSION.M_CR8_CM_FED', 'CRES.G8.THE_CH.ACTS_OF_COMPASSION.COMPASSION', 'Thinks the king in Matthew 25 praises big religious deeds and leaves out ordinary acts such as feeding the hungry.', '{"question":"Which act does the king name in Matthew 25:35?","wrong_answer":"Building a large church","correct_answer":"Feeding the hungry"}'::jsonb, 'The learner thinks only big religious deeds count with God.', 'Offer "Building a large church" beside "Feeding the hungry" and ask the child to choose.', 'Read Matthew 25:35-36 and list the six acts: food, drink, welcome, clothes, care, visiting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_CH.ACTS_OF_COMPASSION.COMPASSION.M_CR8_CM_STRANGER', 'CRES.G8.THE_CH.ACTS_OF_COMPASSION.COMPASSION', 'Says strangers should be avoided.', '{"question":"How should strangers be treated?","wrong_answer":"Turned away","correct_answer":"Welcomed"}'::jsonb, 'Children are taught to be careful with strangers, and the learner applies it to the needy.', 'Offer "Turned away" next to the right answer and ask the question again in a new situation.', 'Separate child safety (stay with trusted adults) from welcoming strangers in need as a family or church (Matthew 25:35).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_CH.ACTS_OF_COMPASSION.COMPASSION.M_CR8_CM_LEAST', 'CRES.G8.THE_CH.ACTS_OF_COMPASSION.COMPASSION', 'Misreads "the least of these".', '{"question":"What does the king say about helping the least?","wrong_answer":"It is for nothing","correct_answer":"It was done for Him"}'::jsonb, 'Small acts seem not to matter.', 'Offer "It is for nothing" next to the right answer and ask the question again in a new situation.', 'Read Matthew 25:40: "you did for me". Helping the least is serving Christ.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.THE_CH.ACTS_OF_COMPASSION.COMPASSION.M_CR8_CM_INHERIT_RICH', 'CRES.G8.THE_CH.ACTS_OF_COMPASSION.COMPASSION', 'Thinks those who inherit the kingdom in Matthew 25 are the rich or important.', '{"question":"Who will inherit the kingdom, according to Matthew 25:34-40?","wrong_answer":"The rich and important","correct_answer":"Those who showed love to the least: fed, welcomed, clothed and visited them"}'::jsonb, 'The learner links inheritance with wealth.', 'Offer "The rich and important" beside "Those who showed love to the least: fed, welcomed, clothed and visited them" and ask the child to choose.', 'Read Matthew 25:34-36: "come, you who are blessed... for I was hungry and you gave me something to eat".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.FAMILY_RELATIONSHIPS.FAMILY_ROLES.M_CR8_FRL_PARENT', 'CRES.G8.CHRIST.FAMILY_RELATIONSHIPS.FAMILY_ROLES', 'Thinks parents only punish, missing that they provide, guide and care.', '{"question":"What do parents do for children?","wrong_answer":"Only punish them","correct_answer":"Provide, guide and care for them"}'::jsonb, 'Discipline is the part of parenting the learner notices most.', 'Offer "Only punish them" next to the right answer and ask the question again in a new situation.', 'List what parents do: provide, protect, guide, teach, love, discipline (Ephesians 6:4; Proverbs 22:6).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.FAMILY_RELATIONSHIPS.FAMILY_ROLES.M_CR8_FRL_HEALTHY', 'CRES.G8.CHRIST.FAMILY_RELATIONSHIPS.FAMILY_ROLES', 'Picks shouting at each other as a healthy family practice, because it is common.', '{"question":"Which is a healthy family practice?","wrong_answer":"Shouting at each other","correct_answer":"Talking and forgiving"}'::jsonb, 'Shouting is common in some homes and seems normal.', 'Offer "Shouting at each other" next to the right answer and ask the question again in a new situation.', 'Contrast healthy practices (talking, forgiving, praying, eating together) with harmful ones (shouting, silence, violence).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.FAMILY_RELATIONSHIPS.FAMILY_ROLES.M_CR8_FRL_CHILD', 'CRES.G8.CHRIST.FAMILY_RELATIONSHIPS.FAMILY_ROLES', 'Thinks Ephesians 6:1 lets teenagers ignore their parents.', '{"question":"What does Ephesians 6:1 say children should do?","wrong_answer":"Ignore their parents","correct_answer":"Obey their parents"}'::jsonb, 'Teenagers seek independence and read obedience as childish.', 'Offer "Ignore their parents" next to the right answer and ask the question again in a new situation.', 'Read Ephesians 6:1-3 and Colossians 3:20; discuss obeying "in the Lord", in what is right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.FAMILY_RELATIONSHIPS.FAMILY_ROLES.M_CR8_FRL_CONFLICT_SILENCE', 'CRES.G8.CHRIST.FAMILY_RELATIONSHIPS.FAMILY_ROLES', 'Thinks the best solution to family conflict is silence and avoiding each other.', '{"question":"Which is a good solution to a conflict in the family?","wrong_answer":"Stop talking to each other until it goes away","correct_answer":"Talk calmly, listen, forgive and, if needed, seek help from an elder or pastor"}'::jsonb, 'Avoiding the problem feels safer than facing it.', 'Offer "Stop talking to each other until it goes away" beside "Talk calmly, listen, forgive and, if needed, seek help from an elder or pastor" and ask the child to choose.', 'Read Matthew 18:15 and Ephesians 4:26, 32: go and talk, do not let anger last, forgive.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.ABUSE_SAFETY.M_CR8_AS_TELL', 'CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.ABUSE_SAFETY', 'Says to keep it secret.', '{"question":"What should a child do if someone hurts or frightens her?","wrong_answer":"Keep it secret","correct_answer":"Tell a trusted adult"}'::jsonb, 'Fear, shame or threats make a young person keep silent.', 'Offer "Keep it secret" next to the right answer and ask the question again in a new situation.', 'Repeat: it is never your fault; tell a trusted adult or Childline 116, and keep telling until someone helps.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.ABUSE_SAFETY.M_CR8_AS_MEANING', 'CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.ABUSE_SAFETY', 'Thinks abuse means only beating, missing sexual, emotional and online abuse and neglect.', '{"question":"Which of these is a form of abuse?","wrong_answer":"Only beating","correct_answer":"Sexual, physical or emotional abuse, neglect, or online abuse"}'::jsonb, 'The learner thinks abuse must be violent to count.', 'Offer "Only beating" beside "Sexual, physical or emotional abuse, neglect, or online abuse" and ask the child to choose.', 'Name forms: physical, sexual, emotional (insults, threats), neglect, online. Any of them is abuse.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.ABUSE_SAFETY.M_CR8_AS_VALUE', 'CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.ABUSE_SAFETY', 'Picks going along with others to avoid trouble as a value that keeps people safe, instead of self-respect and assertiveness.', '{"question":"Which value or life skill helps a youth stay safe from abuse?","wrong_answer":"Going along with others to avoid trouble","correct_answer":"Assertiveness and self-respect"}'::jsonb, 'The learner picks a word without linking it to safety.', 'Offer "Going along with others to avoid trouble" beside "Assertiveness and self-respect" and ask the child to choose.', 'Link each value to an action: self-control (keep away from risky places), assertiveness (say no), respect (for self and others).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.TEEN_PREGNANCY.M_CR8_TP_GIRL_FAULT', 'CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.TEEN_PREGNANCY', 'Blames only the girl for a teenage pregnancy, forgetting the boy or adult involved and abuse.', '{"question":"Who is responsible when a schoolgirl becomes pregnant?","wrong_answer":"Only the girl","correct_answer":"Both people involved; and if an adult took advantage, the adult has committed a crime"}'::jsonb, 'The learner has heard blame placed on girls alone.', 'Offer "Only the girl" beside "Both people involved; and if an adult took advantage, the adult has committed a crime" and ask the child to choose.', 'Discuss responsibility of both and the law on adults who abuse children. Never blame a victim.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.TEEN_PREGNANCY.M_CR8_TP_GIFTS_HARMLESS', 'CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.TEEN_PREGNANCY', 'Thinks accepting money or gifts from an older person has nothing to do with teenage pregnancy.', '{"question":"Why can gifts from an older person lead to teenage pregnancy?","wrong_answer":"They cannot; gifts are only kindness","correct_answer":"The person may expect sex in return, which is exploitation"}'::jsonb, 'Poverty makes gifts welcome and the learner does not see the trap.', 'Offer "They cannot; gifts are only kindness" beside "The person may expect sex in return, which is exploitation" and ask the child to choose.', 'Name gifts for favours as a warning sign; practise refusing and telling a trusted adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.TEEN_PREGNANCY.M_CR8_TP_ONCE_SAFE', 'CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.TEEN_PREGNANCY', 'Thinks pregnancy or infection cannot happen the first time.', '{"question":"Can a girl become pregnant the first time she has sex?","wrong_answer":"No, never the first time","correct_answer":"Yes, it can happen the first time"}'::jsonb, 'Myths passed among friends.', 'Offer "No, never the first time" beside "Yes, it can happen the first time" and ask the child to choose.', 'Correct the myth plainly and send learners to a health worker or counsellor for questions.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.TEEN_PREGNANCY.M_CR8_TP_NO_FUTURE', 'CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.TEEN_PREGNANCY', 'Thinks a girl who becomes pregnant can never return to school or have a future.', '{"question":"Can a girl who becomes pregnant continue her education in Kenya?","wrong_answer":"No, her life is over","correct_answer":"Yes: the school re-entry policy lets her return, and her family and church should support her"}'::jsonb, 'Stigma makes the learner see pregnancy as the end.', 'Offer "No, her life is over" beside "Yes: the school re-entry policy lets her return, and her family and church should support her" and ask the child to choose.', 'Explain that girls may return to school; show compassion (John 8:10-11) while teaching responsibility.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.ABUSE_SAFETY.M_CR8_AS_KNOWN_SAFE', 'CRES.G8.CHRIST.HUMAN_SEXUALITY_RESPONSI.ABUSE_SAFETY', 'Thinks abuse comes only from strangers, never from relatives, teachers or neighbours.', '{"question":"Who can abuse a young person?","wrong_answer":"Only strangers","correct_answer":"Anyone, including people the young person knows"}'::jsonb, 'The learner has been warned mainly about strangers.', 'Offer "Only strangers" beside "Anyone, including people the young person knows" and ask the child to choose.', 'Explain that abusers are often known people; the rule is the same: say no, get away, tell.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_SACRED.M_CR8_LF_GIFT', 'CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_SACRED', 'Thinks life comes from chance only, missing that Christians see it as God''s gift.', '{"question":"Where does life come from?","wrong_answer":"From chance only","correct_answer":"From God as a gift"}'::jsonb, 'The learner has heard life described as chance or evolution only.', 'Offer "From chance only" next to the right answer and ask the question again in a new situation.', 'Read Genesis 2:7 and Psalm 139:13: God gives life and forms each person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_SACRED.M_CR8_LF_COMMAND', 'CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_SACRED', 'Gives "you shall not steal" for Exodus 20:13 instead of "you shall not murder".', '{"question":"What does Exodus 20:13 say?","wrong_answer":"You shall not steal","correct_answer":"You shall not murder"}'::jsonb, 'The learner recalls the commandments as a list and picks the wrong one.', 'Offer "You shall not steal" next to the right answer and ask the question again in a new situation.', 'Read Exodus 20:13 and link "do not murder" to the sacredness of life.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_SACRED.M_CR8_LF_HELP', 'CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_SACRED', 'Says to hide hopeless feelings.', '{"question":"What should a child do who feels hopeless?","wrong_answer":"Hide it","correct_answer":"Tell a trusted adult or counsellor"}'::jsonb, 'Shame and fear of being a burden make the learner hide hopeless feelings.', 'Offer "Hide it" next to the right answer and ask the question again in a new situation.', 'Name trusted adults and Childline 116; say that asking for help is brave.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_THREATS.M_CR8_LT_TALK_HARM', 'CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_THREATS', 'Thinks talking to someone about suicidal feelings will put the idea in their head, so it is better to say nothing.', '{"question":"A friend says she feels life is not worth living. What should you do?","wrong_answer":"Say nothing and change the subject","correct_answer":"Listen, take it seriously and tell a trusted adult at once"}'::jsonb, 'The learner fears making things worse and feels it is not his business.', 'Offer "Say nothing and change the subject" beside "Listen, take it seriously and tell a trusted adult at once" and ask the child to choose.', 'Teach: listen, take it seriously, do not keep it secret, tell a trusted adult now. Name Childline 116.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_THREATS.M_CR8_LT_WEAK_PEOPLE', 'CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_THREATS', 'Thinks only weak or faithless people struggle with hopeless feelings.', '{"question":"Can a strong Christian feel hopeless?","wrong_answer":"No, only weak people feel that way","correct_answer":"Yes: Elijah and others felt this; God cares and help is there"}'::jsonb, 'The learner thinks faith should stop all dark feelings.', 'Offer "No, only weak people feel that way" beside "Yes: Elijah and others felt this; God cares and help is there" and ask the child to choose.', 'Read 1 Kings 19:4-8: Elijah asked to die, and God gave him rest, food and care. Seeking help is wise.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_THREATS.M_CR8_LT_ABORTION_NO_EFFECT', 'CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_THREATS', 'Thinks an unsafe abortion has no effect on a girl afterwards.', '{"question":"Name one consequence of unsafe abortion for a teenage girl.","wrong_answer":"There are no consequences","correct_answer":"Serious health risks, even death, and lasting guilt or trauma"}'::jsonb, 'The learner has heard it described as a quick way out.', 'Offer "There are no consequences" beside "Serious health risks, even death, and lasting guilt or trauma" and ask the child to choose.', 'List health, emotional, spiritual and legal consequences; teach compassion and where to get help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_THREATS.M_CR8_LT_ONLY_MURDER', 'CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_THREATS', 'Thinks violating the right to life means only murder, not also suicide, abortion, mob justice or reckless driving.', '{"question":"Which of these violates the right to life?","wrong_answer":"Only murder","correct_answer":"Murder, mob justice, suicide, unsafe abortion and reckless driving"}'::jsonb, 'Exodus 20:13 is remembered as about murder alone.', 'Offer "Only murder" beside "Murder, mob justice, suicide, unsafe abortion and reckless driving" and ask the child to choose.', 'Make a list with the class and link each to the sacredness of life (Genesis 1:27; Exodus 20:13).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_SACRED.M_CR8_LF_IMAGE', 'CRES.G8.CHRIST.SACREDNESS_OF_LIFE.LIFE_SACRED', 'Thinks life is sacred only for good or important people.', '{"question":"Why is every human life sacred, according to Genesis 1:27 and 9:6?","wrong_answer":"Only good people''s lives are sacred","correct_answer":"Every person is made in the image of God"}'::jsonb, 'The learner judges worth by behaviour or status.', 'Offer "Only good people''s lives are sacred" beside "Every person is made in the image of God" and ask the child to choose.', 'Read Genesis 9:6: because God made people in his image, every life is protected.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.BULLYING.BULLYING.M_CR8_BL_CAUSE', 'CRES.G8.CHRIST.BULLYING.BULLYING', 'Names kindness as a cause of bullying, instead of the wish for power, jealousy or having been bullied.', '{"question":"Which can cause bullying?","wrong_answer":"Kindness","correct_answer":"Wanting power over others"}'::jsonb, 'The learner does not know what drives bullies.', 'Offer "Kindness" next to the right answer and ask the question again in a new situation.', 'List causes: wanting power, being bullied at home, peer pressure, jealousy, prejudice. Discuss each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.BULLYING.BULLYING.M_CR8_BL_EFFECT', 'CRES.G8.CHRIST.BULLYING.BULLYING', 'Thinks bullying is only a joke with no lasting effect.', '{"question":"Which is an effect of bullying?","wrong_answer":"Happiness","correct_answer":"Fear and loneliness"}'::jsonb, 'Bullying is sometimes laughed off as a joke.', 'Offer "Happiness" next to the right answer and ask the question again in a new situation.', 'List effects on the person (fear, loneliness, falling marks, depression) and on the family (worry, moving schools).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.BULLYING.BULLYING.M_CR8_BL_VALUE', 'CRES.G8.CHRIST.BULLYING.BULLYING', 'Picks toughness as the value that stops bullying, instead of love and kindness.', '{"question":"Which value from Ephesians 4:32 helps stop bullying?","wrong_answer":"Being tough so no one dares touch you","correct_answer":"Being kind and compassionate"}'::jsonb, 'The learner picks any word without linking it to bullying.', 'Offer "Being tough so no one dares touch you" beside "Being kind and compassionate" and ask the child to choose.', 'Read Romans 12:10 and Ephesians 4:32: love, honour, kindness, forgiveness. Link each to standing up for others.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.BULLYING.BULLYING.M_CR8_BL_BYSTANDER', 'CRES.G8.CHRIST.BULLYING.BULLYING', 'Thinks a learner who watches bullying and says nothing is not involved.', '{"question":"You see a classmate being bullied. What does love require?","wrong_answer":"Stay out of it; it is not my business","correct_answer":"Stand with the victim and report it to a teacher"}'::jsonb, 'Fear of becoming the next target makes bystanding feel safe.', 'Offer "Stay out of it; it is not my business" beside "Stand with the victim and report it to a teacher" and ask the child to choose.', 'Discuss the bystander: silence helps the bully. Read Proverbs 31:8: speak up for those who cannot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.WORK_TALENTS_GIFTS_AND_A.TALENTS_PARABLE.M_CR8_TP_NUMBER', 'CRES.G8.CHRIST.WORK_TALENTS_GIFTS_AND_A.TALENTS_PARABLE', 'Says the first servant received one talent instead of five.', '{"question":"How many talents did the first servant get?","wrong_answer":"One","correct_answer":"Five"}'::jsonb, 'The third servant is remembered best.', 'Offer "One" next to the right answer and ask the question again in a new situation.', 'Draw three bags: 5, 2, 1, "each according to his ability" (Matthew 25:15).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.WORK_TALENTS_GIFTS_AND_A.TALENTS_PARABLE.M_CR8_TP_BURY', 'CRES.G8.CHRIST.WORK_TALENTS_GIFTS_AND_A.TALENTS_PARABLE', 'Thinks the third servant traded and doubled his talent, instead of burying it.', '{"question":"What did the third servant do?","wrong_answer":"Traded and doubled","correct_answer":"Buried the talent"}'::jsonb, 'The learner mixes the servants'' actions.', 'Offer "Traded and doubled" next to the right answer and ask the question again in a new situation.', 'Read 25:16-18 and match each servant with what he did.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.WORK_TALENTS_GIFTS_AND_A.TALENTS_PARABLE.M_CR8_TP_LESSON', 'CRES.G8.CHRIST.WORK_TALENTS_GIFTS_AND_A.TALENTS_PARABLE', 'Thinks the lesson is to keep what one has hidden and safe, instead of using it faithfully.', '{"question":"What does the parable teach?","wrong_answer":"Hide what you have","correct_answer":"Use what you have faithfully"}'::jsonb, 'The learner thinks keeping safe is wise.', 'Offer "Hide what you have" next to the right answer and ask the question again in a new situation.', 'Read 25:25-27: fear made him hide it; the master wanted it used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.WORK_TALENTS_GIFTS_AND_A.TALENTS_PARABLE.M_CR8_TP_FEAR_REASON', 'CRES.G8.CHRIST.WORK_TALENTS_GIFTS_AND_A.TALENTS_PARABLE', 'Misses why the third servant hid his talent: he was afraid and thought the master hard.', '{"question":"Why did the third servant bury his talent (Matthew 25:24-25)?","wrong_answer":"He forgot about it","correct_answer":"He was afraid and thought the master was a hard man"}'::jsonb, 'The learner has not read the servant''s own words.', 'Offer "He forgot about it" beside "He was afraid and thought the master was a hard man" and ask the child to choose.', 'Read 25:24-25 and discuss fear as a reason people do not use their gifts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.LEISURE.LEISURE.M_CR8_LE_MEANING', 'CRES.G8.CHRIST.LEISURE.LEISURE', 'Thinks leisure means hard work, instead of free time after duties.', '{"question":"What is leisure?","wrong_answer":"Hard work","correct_answer":"Free time"}'::jsonb, 'The learner confuses free time with chores done in free time.', 'Offer "Hard work" next to the right answer and ask the question again in a new situation.', 'Define leisure: free time after work and duties, for rest and good activities.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.LEISURE.LEISURE.M_CR8_LE_MISUSE', 'CRES.G8.CHRIST.LEISURE.LEISURE', 'Calls reading a misuse of leisure, linking it with school work.', '{"question":"Which is a misuse of leisure?","wrong_answer":"Reading a book","correct_answer":"Gambling or taking drugs"}'::jsonb, 'Reading is linked with school work, so it feels like a chore.', 'Offer "Reading a book" next to the right answer and ask the question again in a new situation.', 'Sort activities: builds up (reading, sport, hobbies, serving) and pulls down (drugs, gambling, idleness).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.LEISURE.LEISURE.M_CR8_LE_GOOD', 'CRES.G8.CHRIST.LEISURE.LEISURE', 'Thinks idling all day is a constructive use of leisure.', '{"question":"Which is a constructive use of leisure?","wrong_answer":"Idling all day","correct_answer":"Sport or helping at home"}'::jsonb, 'Idling feels restful and harmless.', 'Offer "Idling all day" next to the right answer and ask the question again in a new situation.', 'Read 2 Thessalonians 3:11 and Proverbs 6:9-11: idleness leads to trouble and want.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G8.CHRIST.LEISURE.LEISURE.M_CR8_LE_NO_VALUES', 'CRES.G8.CHRIST.LEISURE.LEISURE', 'Thinks no values are needed in leisure time because it is free time.', '{"question":"Which value helps a youth use leisure well?","wrong_answer":"None: free time needs no rules","correct_answer":"Self-control and time management"}'::jsonb, 'Free time feels like time without rules.', 'Offer "None: free time needs no rules" beside "Self-control and time management" and ask the child to choose.', 'Compile values and life skills for leisure: self-control, time management, responsibility, decision-making. Read Ephesians 5:15-16.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
